head.script:
scwin.dateMask = function(value) {
    if (typeof value == "number") {
        value = value + "";
    }
    var delimiter1 = "-";
    var delimiter2 = "-";
    var delPos1 = 4;
    var delPos2 = 6;
    var maxCharLength = 8;
    // remove delimiter
    value = value.replace(new RegExp(delimiter1), "");
    value = value.replace(new RegExp(delimiter2), "");
    // limit max length
    if (value.length > maxCharLength) {
        value = value.substr(0, maxCharLength);
    }
    // 1st delimiter
    if (value.length > delPos1) {
        value = value.substr(0, delPos1) + delimiter1 + value.substr(delPos1)
    }
    // 2nd delimiter
    if (value.length > delPos2 + delimiter1.length) {
        var cutPos = delPos2 + delimiter1.length;
        value = value.substr(0, cutPos) + delimiter2 + value.substr(cutPos);
    }
    return value;
}
scwin.dateMask_yearMonth = function(value) {
    if (typeof value == "number") {
        value = value + "";
    }
    var delimiter1 = "-";
    var delimiter2 = "-";
    var delPos1 = 4;
    var maxCharLength = 6;
    // remove delimiter
    value = value.replace(new RegExp(delimiter1), "");
    // limit max length
    if (value.length > maxCharLength) {
        value = value.substr(0, maxCharLength);
    }
    // 1st delimiter
    if (value.length > delPos1) {
        value = value.substr(0, delPos1) + delimiter1 + value.substr(delPos1)
    }
    return value;
}
scwin.fireKeyEvent = function(inputCalendarId, value) {
    var obj = window[inputCalendarId];
    var input = WebSquare.wUnit.getDomById($p.id + inputCalendarId + "_input")
    if (obj && input) {
        if (obj.focus) {
            obj.focus();
        }
        for (var i = 0; i < value.length; i++) {
            var keyCode = value.charCodeAt(i);
            var event = {
                charCode: keyCode,
                keyCode: keyCode
            }
            if (obj.handleKeydownEvent) {
                obj.handleKeydownEvent(event);
            }
            if (obj.handleKeypressEvent) {
                obj.handleKeypressEvent(event);
            }
            input.value = input.value + String.fromCharCode(keyCode);
            if (obj.handleKeyupEvent) {
                obj.handleKeyupEvent(event);
            }
        }
        if (obj.blur) {
            obj.blur();
        }
    }
}
scwin.getInputValue = function(inputCalendarId) {
    var dom = WebSquare.wUnit.getDomById($p.id + inputCalendarId + "_input");
    if (dom) {
        return dom.value;
    }
    return null;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 "엑셀다운로드"버튼을 클릭한다.
    WebSquare.wUnit.addCommand('assert', "inputCalendar2.options.placeholder == 'yyyyMMdd'", 'true');
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand('assert', "inputCalendar3.options.placeholder == 'yyyyMM'", 'true');
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand('assert', "inputCalendar8.options.placeholder == 'yyyyMMdd HH:mm:SS'", 'true');
    WebSquare.wUnit.addCommand('pause', '500');
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
}
